import sys

MOD = 998244353
G = 3


def ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(G, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for i in range(0, n, length):
            w = 1
            for j in range(i, i + half):
                u = a[j]
                v = a[j + half] * w % MOD
                a[j] = (u + v) % MOD
                a[j + half] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def convolution(a, b):
    if not a or not b:
        return []
    if min(len(a), len(b)) <= 32:
        res = [0] * (len(a) + len(b) - 1)
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    res[i + j] = (res[i + j] + x * y) % MOD
        return res

    need = len(a) + len(b) - 1
    n = 1
    while n < need:
        n <<= 1

    fa = a[:] + [0] * (n - len(a))
    fb = b[:] + [0] * (n - len(b))
    ntt(fa, False)
    ntt(fb, False)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    ntt(fa, True)
    return fa[:need]


def main():
    input = sys.stdin.readline
    N = int(input())
    S = input().strip()

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    # Events are cuts immediately after a W.
    # t = number of Ws seen, b = number of Bs seen.
    events_b = []
    bcnt = 0
    for ch in S:
        if ch == 'B':
            bcnt += 1
        else:
            events_b.append(bcnt)

    if len(events_b) != N or S[-1] != 'W':
        print(0)
        return

    first_zero = [0] * N
    contribution = [0] * N

    def cdq(l, r):
        if r - l == 1:
            t = l + 1
            b = events_b[l]
            if b <= t:
                # Number of arbitrary partial matchings where all b black
                # vertices in the prefix are matched.
                total = fact[t] * pow(fact[t - b], MOD - 2, MOD) % MOD
                first_zero[l] = (
                    total - contribution[l]
                ) * pow(fact[t - b], MOD - 2, MOD) % MOD
            return

        m = (l + r) >> 1
        cdq(l, m)

        # Add contributions from first-zero events in [l, m)
        # to all events in [m, r).
        left_indices = []
        min_b = N + 1
        max_b = -1
        for i in range(l, m):
            if first_zero[i]:
                bi = events_b[i]
                left_indices.append(i)
                if bi < min_b:
                    min_b = bi
                if bi > max_b:
                    max_b = bi

        if left_indices:
            max_t = r  # t ranges up to r
            src = [0] * (max_b - min_b + 1)
            for i in left_indices:
                src[events_b[i] - min_b] = (
                    src[events_b[i] - min_b] + first_zero[i]
                ) % MOD

            # Kernel value at x is x!, for x >= 0.
            ker = fact[:max_t - min_b + 1]
            conv = convolution(src, ker)

            for i in range(m, r):
                t = i + 1
                idx = t - min_b
                if 0 <= idx < len(conv):
                    contribution[i] = (contribution[i] + conv[idx]) % MOD

        cdq(m, r)

    cdq(0, N)
    print(first_zero[N - 1] % MOD)


if __name__ == "__main__":
    main()

import sys
from bisect import bisect_left, bisect_right
from array import array


def process(intervals, indices, n, m, bad):
    if not indices:
        return

    base = 1
    while base < n:
        base <<= 1

    coords = [[] for _ in range(2 * base)]

    for idx in indices:
        l, r = intervals[idx]
        p = base + l - 1
        while p:
            coords[p].append(r)
            p >>= 1

    seg = [None] * (2 * base)
    for i in range(2 * base):
        if coords[i]:
            a = coords[i]
            a.sort()
            seg[i] = array('i', [0]) * (2 * len(a))

    def update(l, r, value):
        p = base + l - 1
        while p:
            a = coords[p]
            t = seg[p]
            q = bisect_left(a, r) + len(a)
            if t[q] < value:
                t[q] = value
                q >>= 1
                while q:
                    nv = t[q << 1]
                    if t[q << 1 | 1] > nv:
                        nv = t[q << 1 | 1]
                    if t[q] >= nv:
                        break
                    t[q] = nv
                    q >>= 1
            p >>= 1

    def node_query(node, low, high):
        a = coords[node]
        if not a:
            return 0
        left = bisect_left(a, low) + len(a)
        right = bisect_right(a, high) + len(a)
        t = seg[node]
        res = 0
        while left < right:
            if left & 1:
                if t[left] > res:
                    res = t[left]
                left += 1
            if right & 1:
                right -= 1
                if t[right] > res:
                    res = t[right]
            left >>= 1
            right >>= 1
        return res

    def query(left_l, right_l, low_r, high_r):
        if left_l > right_l or low_r > high_r:
            return 0
        left = base + left_l - 1
        right = base + right_l
        res = 0
        while left < right:
            if left & 1:
                v = node_query(left, low_r, high_r)
                if v > res:
                    res = v
                left += 1
            if right & 1:
                right -= 1
                v = node_query(right, low_r, high_r)
                if v > res:
                    res = v
            left >>= 1
            right >>= 1
        return res

    for idx in indices:
        l, r = intervals[idx]

        # Previous interval starts to the left and ends inside (l, r).
        v = query(1, l - 1, l + 1, r - 1)
        if v > bad[idx]:
            bad[idx] = v

        # Previous interval starts inside (l, r) and ends to the right.
        v = query(l + 1, r - 1, r + 1, n)
        if v > bad[idx]:
            bad[idx] = v

        update(l, r, idx)


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)

    n = next(it)
    m = next(it)
    q = next(it)

    intervals = [(0, 0)] * (m + 1)
    positive = []
    negative = []

    for i in range(1, m + 1):
        s = next(it)
        t = next(it)
        if s < t:
            intervals[i] = (s, t)
            positive.append(i)
        else:
            intervals[i] = (t, s)
            negative.append(i)

    bad = [0] * (m + 1)

    process(intervals, positive, n, m, bad)
    process(intervals, negative, n, m, bad)

    base = 1
    while base < m + 1:
        base <<= 1
    rmq = [0] * (2 * base)
    for i in range(1, m + 1):
        rmq[base + i] = bad[i]
    for i in range(base - 1, 0, -1):
        rmq[i] = max(rmq[i << 1], rmq[i << 1 | 1])

    def range_max(left, right):
        left += base
        right += base + 1
        res = 0
        while left < right:
            if left & 1:
                res = max(res, rmq[left])
                left += 1
            if right & 1:
                right -= 1
                res = max(res, rmq[right])
            left >>= 1
            right >>= 1
        return res

    out = []
    for _ in range(q):
        l = next(it)
        r = next(it)
        if l == r or range_max(l + 1, r) < l:
            out.append("Yes")
        else:
            out.append("No")

    sys.stdout.write("\n".join(out))


