from typing import List


class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)

        if abs(k) > 12 * n:
            return -1

        # dp[parity][alternating_sum] = set of reachable products
        # parity is the subsequence length modulo 2.
        dp = [{}, {}]

        for i, x in enumerate(nums):
            remaining = n - i - 1

            # Snapshot both parity layers so the current number is used at most once.
            snapshot = [
                [(s, tuple(products)) for s, products in dp[0].items()],
                [(s, tuple(products)) for s, products in dp[1].items()],
            ]

            # Start a new subsequence with nums[i].
            if abs(x - k) <= 12 * remaining:
                dp[1].setdefault(x, set()).add(x)

            # Extend all previously formed subsequences.
            for parity in (0, 1):
                sign = 1 if parity == 0 else -1
                sum_delta = sign * x
                next_parity = 1 - parity

                for current_sum, products in snapshot[parity]:
                    new_sum = current_sum + sum_delta

                    if abs(new_sum - k) > 12 * remaining:
                        continue

                    target = dp[next_parity].setdefault(new_sum, set())

                    if x == 0:
                        if products:
                            target.add(0)
                    elif x == 1:
                        target.update(products)
                    else:
                        for product in products:
                            new_product = product * x
                            if new_product <= limit:
                                target.add(new_product)

        answer = -1
        for parity in (0, 1):
            products = dp[parity].get(k)
            if products:
                answer = max(answer, max(products))

        return answer

import sys


def solve_case(n, k, cakes):
    m = 2 * k

    best_val = [0] * n
    base_group = [0] * n

    for i, (x, y, z) in enumerate(cakes):
        if x >= y and x >= z:
            best_val[i] = x
            base_group[i] = 0
        elif y >= z:
            best_val[i] = y
            base_group[i] = 1
        else:
            best_val[i] = z
            base_group[i] = 2

    order = sorted(range(n), key=lambda i: best_val[i], reverse=True)
    rank = [0] * n
    for r, i in enumerate(order):
        rank[i] = r

    group_values = [[], [], []]
    for i in range(n):
        group_values[base_group[i]].append(best_val[i])

    for g in range(3):
        group_values[g].sort(reverse=True)

    prefixes = []
    for g in range(3):
        p = [0]
        s = 0
        for v in group_values[g]:
            s += v
            p.append(s)
        prefixes.append(p)

    def prepare(length):
        counts = [0, 0, 0]
        total = 0
        for r in range(length):
            idx = order[r]
            g = base_group[idx]
            counts[g] += 1
            total += best_val[idx]
        return counts, total

    def select_with_parity(length, target_mask, excluded=-1):
        counts, total = prepare(length)

        if excluded != -1 and rank[excluded] < length:
            removed_group = base_group[excluded]
            replacement = order[length]
            added_group = base_group[replacement]

            counts[removed_group] -= 1
            counts[added_group] += 1
            total += best_val[replacement] - best_val[excluded]

        current_mask = 0
        for g in range(3):
            if counts[g] & 1:
                current_mask |= 1 << g

        if current_mask == target_mask:
            return total

        differing = [g for g in range(3) if ((current_mask ^ target_mask) >> g) & 1]
        if len(differing) != 2:
            return None

        a, b = differing
        best_gain = None

        # Move one selected item from a to b.
        if counts[a] > 0 and counts[b] < len(group_values[b]):
            gain = group_values[b][counts[b]] - group_values[a][counts[a] - 1]
            best_gain = gain

        # Move one selected item from b to a.
        if counts[b] > 0 and counts[a] < len(group_values[a]):
            gain = group_values[a][counts[a]] - group_values[b][counts[b] - 1]
            if best_gain is None or gain > best_gain:
                best_gain = gain

        if best_gain is None:
            return None
        return total + best_gain

    answer = select_with_parity(m, 0)
    if answer is None:
        answer = -10**30

    for i, (x, y, z) in enumerate(cakes):
        c = base_group[i]
        vals = (x, y, z)

        for d in range(3):
            if d == c:
                continue

            loss = best_val[i] - vals[d]
            remaining = select_with_parity(m - 1, 1 << d, i)
            if remaining is not None:
                candidate = remaining + vals[d]
                if candidate > answer:
                    answer = candidate

    return answer


def main():
    input = sys.stdin.buffer.readline
    t = int(input())
    out = []

    for _ in range(t):
        n, k = map(int, input().split())
        cakes = [tuple(map(int, input().split())) for _ in range(n)]
        out.append(str(solve_case(n, k, cakes)))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

import sys

def solve():
    data = sys.stdin.read().split()
    n = int(data[0])
    s = data[1]
    t = data[2]

    mapping = [-1] * 26

    for a, b in zip(s, t):
        x = ord(a) - ord('a')
        y = ord(b) - ord('a')
        if mapping[x] == -1:
            mapping[x] = y
        elif mapping[x] != y:
            print(-1)
            return

    edge_count = sum(
        1 for x in range(26)
        if mapping[x] != -1 and mapping[x] != x
    )

    state = [0] * 26
    cycles = 0

    for start in range(26):
        if state[start] != 0:
            continue
        if mapping[start] == -1 or mapping[start] == start:
            state[start] = 2
            continue

        path = []
        cur = start

        while (
            cur != -1
            and mapping[cur] != -1
            and mapping[cur] != cur
            and state[cur] == 0
        ):
            state[cur] = 1
            path.append(cur)
            cur = mapping[cur]

        if (
            cur != -1
            and mapping[cur] != -1
            and mapping[cur] != cur
            and state[cur] == 1
        ):
            cycles += 1

        for v in path:
            state[v] = 2

    if cycles > 0 and len(set(s)) == 26:
        print(-1)
    else:
        print(edge_count + cycles)

