    solve()

import sys


def solve():
    input = sys.stdin.readline
    t = int(input())
    out = []
    SHIFT = 100000000

    for _ in range(t):
        R, B = map(int, input().split())

        if R % 2 == 1 or (R == 0 and B % 2 == 1):
            out.append("No")
            continue

        out.append("Yes")

        if R == 0:
            if B == 2:
                uv = [(0, 0), (1, 0)]
            else:
                a = 1
                b = B // 2 - 1
                uv = [(0, 0)]

                for i in range(1, a + 1):
                    uv.append((i, 0))
                for j in range(1, b + 1):
                    uv.append((a, j))
                for i in range(a - 1, -1, -1):
                    uv.append((i, b))
                for j in range(b - 1, 0, -1):
                    uv.append((0, j))

            for u, v in uv:
                r = u + v + SHIFT
                c = u - v + SHIFT
                out.append(f"B {r} {c}")
            continue

        # Construct a red path from A=(0,0) to X=(1,0).
        # It has R-1 edges.
        red_path = [(0, 0)]
        if R == 2:
            red_path.append((1, 0))
        else:
            w = (R - 2) // 2
            red_path.append((0, -1))
            for x in range(1, w + 1):
                red_path.append((x, -1))
            red_path.append((w, 0))
            for x in range(w - 1, 0, -1):
                red_path.append((x, 0))
            red_path.append((1, 0))

        X = (0, 0)  # transformed coordinates for (1,0)

        if B == 0:
            positions = red_path
            labels = ["R"] * len(positions)
        else:
            if B % 2 == 1:
                # Blue path from (1,0) to (0,1).
                k = (B - 1) // 2
                blue_uv = [(0, 0)]
                for u in range(1, k + 1):
                    blue_uv.append((u, 0))
                blue_uv.append((k, -1))
                for u in range(k - 1, -1, -1):
                    blue_uv.append((u, -1))
            else:
                # Blue path from (1,0) to (-1,0).
                k = B // 2
                blue_uv = [(0, 0)]
                for u in range(1, k):
                    blue_uv.append((u, 0))
                blue_uv.append((k - 1, -1))
                for u in range(k - 2, -2, -1):
                    blue_uv.append((u, -1))

            # Convert transformed coordinates to ordinary coordinates.
            blue_path = []
            for u, v in blue_uv:
                r = u + v + 1
                c = u - v
                blue_path.append((r, c))

            positions = red_path + blue_path[1:]
            labels = (
                ["R"] * (len(red_path) - 1)
                + ["B"] * B
                + ["R"]
            )

        for label, (r, c) in zip(labels, positions):
            out.append(f"{label} {r + SHIFT} {c + SHIFT}")

    sys.stdout.write("\n".join(out))


