def solve():
    s = sys.stdin.buffer.readline().strip().decode()
    n = len(s)
    rev = s[::-1]

    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and rev[i] != rev[j]:
            j = pi[j - 1]
        if rev[i] == rev[j]:
            j += 1
        pi[i] = j

    matched = 0
    for c in s:
        while matched > 0 and c != rev[matched]:
            matched = pi[matched - 1]
        if c == rev[matched]:
            matched += 1

    answer = s + s[:n - matched][::-1]
    sys.stdout.write(answer + "\n")

