from functools import lru_cache


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            length = len(digits)
            total = 0

            for target_sum in range(1, 9 * length + 1):
                @lru_cache(None)
                def dp(pos: int, digit_sum: int, product_mod: int, tight: bool) -> int:
                    if digit_sum > target_sum:
                        return 0

                    remaining = length - pos
                    if digit_sum + 9 * remaining < target_sum:
                        return 0

                    if pos == length:
                        return int(digit_sum == target_sum and product_mod == 0)

                    limit = digits[pos] if tight else 9
                    result = 0

                    for digit in range(limit + 1):
                        new_sum = digit_sum + digit
                        if new_sum > target_sum:
                            break

                        if digit_sum == 0 and digit == 0:
                            new_product_mod = product_mod
                        else:
                            new_product_mod = (product_mod * digit) % target_sum

                        result += dp(
                            pos + 1,
                            new_sum,
                            new_product_mod,
                            tight and digit == limit
                        )

                    return result

                total += dp(0, 0, 1 % target_sum, True)

            return total

        return count_up_to(r) - count_up_to(l - 1)

from typing import List


class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)

        if n - 1 < k:
            return [0] * n

        children = [{}]
        count = [0]
        depth = [0]
        paths = []
        max_depth = 0

        for word in words:
            node = 0
            path = []

            for ch in word:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)

                node = nxt
                count[node] += 1
                path.append(node)

            paths.append(path)
            max_depth = max(max_depth, len(word))

        active_at_depth = [0] * (max_depth + 1)

        for node in range(1, len(children)):
            if count[node] >= k:
                active_at_depth[depth[node]] += 1

        size = 1
        while size <= max_depth:
            size <<= 1

        tree = [-1] * (2 * size)

        for d in range(1, max_depth + 1):
            if active_at_depth[d] > 0:
                tree[size + d] = d

        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])

        def update_depth(d: int, delta: int) -> None:
            active_at_depth[d] += delta
            pos = size + d
            tree[pos] = d if active_at_depth[d] > 0 else -1
            pos >>= 1

            while pos:
                tree[pos] = max(tree[2 * pos], tree[2 * pos + 1])
                pos >>= 1

        answer = [0] * n

        for i, path in enumerate(paths):
            removed = []

            for node in path:
                if count[node] == k:
                    d = depth[node]
                    update_depth(d, -1)
                    removed.append(d)

            answer[i] = max(0, tree[1])

            for d in removed:
                update_depth(d, 1)

        return answer

