import math

def solve():
    n = int(sys.stdin.readline())

    for d in range(1, 1_000_001):
        if d * d * d > n:
            break
        if n % d != 0:
            continue

        q = n // d
        discriminant = 3 * (4 * q - d * d)
        if discriminant < 0:
            continue

        s = math.isqrt(discriminant)
        if s * s != discriminant:
            continue

        numerator = s - 3 * d
        if numerator <= 0 or numerator % 6 != 0:
            continue

        y = numerator // 6
        x = y + d

        if x > y > 0 and x * x * x - y * y * y == n:
            print(x, y)
            return

    print(-1)

