import sys
from collections import deque

sys.setrecursionlimit(1_000_000)


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def bfs(self, s, t):
        level = [-1] * self.n
        level[s] = 0
        q = deque([s])
        while q:
            v = q.popleft()
            for to, cap, rev in self.g[v]:
                if cap > 0 and level[to] < 0:
                    level[to] = level[v] + 1
                    q.append(to)
        self.level = level
        return level[t] >= 0

    def dfs(self, v, t, f):
        if v == t:
            return f
        g_v = self.g[v]
        while self.it[v] < len(g_v):
            i = self.it[v]
            to, cap, rev = g_v[i]
            if cap > 0 and self.level[v] < self.level[to]:
                d = self.dfs(to, t, min(f, cap))
                if d:
                    g_v[i][1] -= d
                    self.g[to][rev][1] += d
                    return d
            self.it[v] += 1
        return 0

    def max_flow(self, s, t, limit):
        flow = 0
        while flow < limit and self.bfs(s, t):
            self.it = [0] * self.n
            while flow < limit:
                f = self.dfs(s, t, limit - flow)
                if not f:
                    break
                flow += f
        return flow


def main():
    input = sys.stdin.readline
    N, M, K = map(int, input().split())
    edges = []
    for _ in range(M):
        u, v = map(int, input().split())
        edges.append((u - 1, v - 1))

    INF = K + 1

    def feasible(L):
        if L == 0:
            return True

        source = N * L
        sink = source + 1
        dinic = Dinic(sink + 1)

        def node(v, level):
            return v * L + (level - 1)

        for v in range(N):
            for level in range(1, L):
                dinic.add_edge(node(v, level + 1), node(v, level), INF)

        # Vertex 1 must have label 0.
        for level in range(1, L + 1):
            dinic.add_edge(node(0, level), sink, INF)

        # Vertex N must have label at least L.
        for level in range(1, L + 1):
            dinic.add_edge(source, node(N - 1, level), INF)

        for u, v in edges:
            for level in range(1, L + 1):
                # Cost 1 when the label increases across this edge.
                dinic.add_edge(node(v, level), node(u, level), 1)

            for level in range(1, L):
                # Enforce label[v] <= label[u] + 1.
                dinic.add_edge(node(v, level + 1), node(u, level), INF)

        return dinic.max_flow(source, sink, K + 1) <= K

    low, high = 0, N
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)


