def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, k = data[0], data[1]
    vcount = n * k
    adj = [[] for _ in range(vcount)]
    p = 2

    for _ in range(vcount - 1):
        u = data[p] - 1
        v = data[p + 1] - 1
        p += 2
        adj[u].append(v)
        adj[v].append(u)

    if k == 1:
        print("Yes")
        return

    parent = [-1] * vcount
    depth = [0] * vcount
    order = [0]
    parent[0] = vcount

    for v in order:
        for to in adj[v]:
            if to == parent[v]:
                continue
            parent[to] = v
            depth[to] = depth[v] + 1
            order.append(to)

    complete = [False] * vcount
    open_sets = [None] * vcount

    for v in reversed(order):
        children = []
        mandatory = []

        for to in adj[v]:
            if parent[to] == v:
                s = open_sets[to]
                children.append((complete[to], s))
                if not complete[to]:
                    mandatory.append(s)

        m = len(mandatory)
        bad = any(not s for s in mandatory)

        limit = depth[v] + k - 2
        close_target = depth[v] + k - 1
        pair_target = 2 * depth[v] + k - 1

        can_complete = False
        result_set = set()

        if not bad:
            if m == 0:
                # Merge all child open-path endpoint sets.
                sets = [s for _, s in children if s]
                if sets:
                    base = max(sets, key=len)
                    others = [s for s in sets if s is not base]

                    for s in others:
                        if not can_complete:
                            for x in s:
                                if pair_target - x in base:
                                    can_complete = True
                                    break
                        base.update(s)

                    if close_target in base:
                        can_complete = True

                    result_set = base
                else:
                    result_set = set()

                # The path consisting only of v is an available open path.
                result_set.add(depth[v])

            elif m == 1:
                s = mandatory[0]

                if close_target in s:
                    can_complete = True

                # An optional child may be paired with the mandatory one.
                optional = [st for c, st in children if c and st]
                if optional:
                    opt_base = max(optional, key=len)
                    opt_union = opt_base
                    for st in optional:
                        if st is not opt_base:
                            opt_union.update(st)

                    if not can_complete:
                        # Check whether one endpoint from each side gives length K.
                        if len(s) <= len(opt_union):
                            for x in s:
                                if pair_target - x in opt_union:
                                    can_complete = True
                                    break
                        else:
                            for x in opt_union:
                                if pair_target - x in s:
                                    can_complete = True
                                    break

                result_set = s

            elif m == 2:
                a, b = mandatory
                if len(a) > len(b):
                    a, b = b, a

                for x in a:
                    if pair_target - x in b:
                        can_complete = True
                        break

                result_set = set()

        # Endpoint depths too far away would make a path of length at least K+1.
        if result_set:
            result_set.difference_update(
                x for x in result_set if x > limit
            )

        complete[v] = can_complete
        open_sets[v] = result_set

    print("Yes" if complete[0] else "No")


