class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def sum(self, i):
        result = 0
        while i > 0:
            result += self.bit[i]
            i -= i & -i
        return result


def solve():
    input = sys.stdin.readline
    n = int(input())
    p = list(map(int, input().split()))

    pos = [0] * (n + 1)
    for i, value in enumerate(p, 1):
        pos[value] = i

    fw = Fenwick(n)
    for i in range(1, n + 1):
        fw.add(i, 1)

    answer = 0

    for value in range(n, 0, -1):
        current_pos = fw.sum(pos[value])
        moves = value - current_pos
        answer += moves * (current_pos + value - 1) // 2
        fw.add(pos[value], -1)

    print(answer)


