def normal_form(s: str, x: int, y: int):
    runs = []
    pending = deque()

    def add_run(ch, length):
        if length <= 0:
            return
        if runs and runs[-1][0] == ch:
            runs[-1] = (ch, runs[-1][1] + length)
        else:
            runs.append((ch, length))

    def process(ch, length):
        pending.append((ch, length))

        while pending:
            c, v = pending.popleft()
            add_run(c, v)

            while len(runs) >= 2:
                c2, b = runs[-1]
                c1, a = runs[-2]

                if c1 != '1' or c2 != '0' or a < y or b < x:
                    break

                runs.pop()
                runs.pop()

                rem_ones = a % y
                moved_ones = a - rem_ones
                rem_zeros = b % x
                moved_zeros = b - rem_zeros

                parts = []
                if rem_ones:
                    parts.append(('1', rem_ones))
                if moved_zeros:
                    parts.append(('0', moved_zeros))
                if moved_ones:
                    parts.append(('1', moved_ones))
                if rem_zeros:
                    parts.append(('0', rem_zeros))

                for item in reversed(parts):
                    pending.appendleft(item)

                if pending:
                    break

    i = 0
    n = len(s)
    while i < n:
        j = i + 1
        while j < n and s[j] == s[i]:
            j += 1
        process(s[i], j - i)
        i = j

    return tuple(runs)


def main():
    input = sys.stdin.readline
    n, x, y = map(int, input().split())
    s = input().strip()
    t = input().strip()

    print("Yes" if normal_form(s, x, y) == normal_form(t, x, y) else "No")


