class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        by_right = [[] for _ in range(n + 1)]

        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        gains = [0] * m
        total = 0

        top1_a = 0
        top1_id = -1
        top2_a = 0
        top2_id = -1

        for right in range(1, n + 1):
            for a, idx in by_right[right]:
                if a > top1_a:
                    top2_a, top2_id = top1_a, top1_id
                    top1_a, top1_id = a, idx
                elif a > top2_a:
                    top2_a, top2_id = a, idx

            total += right - top1_a

            if top1_id != -1:
                gains[top1_id] += top1_a - top2_a

        return total + max(gains)

