class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # Characters forced by every 'T' occurrence.
        fixed = [-1] * L
        pattern = [ord(c) - 97 for c in str2]

        for i, typ in enumerate(str1):
            if typ == 'T':
                for j, ch in enumerate(pattern):
                    pos = i + j
                    if fixed[pos] != -1 and fixed[pos] != ch:
                        return ""
                    fixed[pos] = ch

        # Prefix-function for KMP.
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and pattern[i] != pattern[j]:
                j = pi[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
            pi[i] = j

        # KMP transitions:
        # trans[q][c] = next state after reading character c
        # hit[q][c]  = whether this character completes an occurrence
        trans = [[0] * 26 for _ in range(m)]
        hit = [[False] * 26 for _ in range(m)]

        for q in range(m):
            for c in range(26):
                k = q
                while k > 0 and pattern[k] != c:
                    k = pi[k - 1]
                if pattern[k] == c:
                    k += 1

                if k == m:
                    hit[q][c] = True
                    k = pi[m - 1]
                trans[q][c] = k

        # A match ending at position p is forbidden exactly when its start
        # position is an 'F' position.
        forbidden_end = [False] * L
        for start in range(n):
            if str1[start] == 'F':
                forbidden_end[start + m - 1] = True

        # can[p][q]: whether positions p..L-1 can be completed when the
        # current KMP state is q.
        can = [None] * (L + 1)
        can[L] = bytearray(b'\x01') * m

        for p in range(L - 1, -1, -1):
            nxt = can[p + 1]
            cur = bytearray(m)
            forced = fixed[p]
            bad_match = forbidden_end[p]

            if forced != -1:
                c = forced
                tr = trans
                ht = hit
                for q in range(m):
                    if (not bad_match or not ht[q][c]) and nxt[tr[q][c]]:
                        cur[q] = 1
            else:
                tr = trans
                ht = hit
                for q in range(m):
                    row_t = tr[q]
                    row_h = ht[q]
                    for c in range(26):
                        if bad_match and row_h[c]:
                            continue
                        if nxt[row_t[c]]:
                            cur[q] = 1
                            break

            can[p] = cur

        if not can[0][0]:
            return ""

        # Reconstruct the lexicographically smallest valid string.
        ans = []
        state = 0

        for p in range(L):
            forced = fixed[p]
            nxt = can[p + 1]
            bad_match = forbidden_end[p]

            if forced != -1:
                c = forced
                if bad_match and hit[state][c]:
                    return ""
                ans.append(chr(c + 97))
                state = trans[state][c]
            else:
                for c in range(26):
                    if bad_match and hit[state][c]:
                        continue
                    ns = trans[state][c]
                    if nxt[ns]:
                        ans.append(chr(c + 97))
                        state = ns
                        break

        return ''.join(ans)

