import math


class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odd = (n + 1) // 2
        even = n // 2
        used = set()
        result = []
        expected_parity = None  # 1 for odd, 0 for even

        def completion_count(remaining_odd: int, remaining_even: int,
                             next_parity: int) -> int:
            remaining = remaining_odd + remaining_even
            if remaining == 0:
                return 1

            odd_slots = (remaining + 1) // 2 if next_parity == 1 else remaining // 2
            even_slots = remaining - odd_slots

            if remaining_odd != odd_slots or remaining_even != even_slots:
                return 0

            return math.factorial(remaining_odd) * math.factorial(remaining_even)

        for position in range(n):
            for value in range(1, n + 1):
                if value in used:
                    continue

                parity = value % 2
                if expected_parity is not None and parity != expected_parity:
                    continue

                new_odd = odd - (parity == 1)
                new_even = even - (parity == 0)

                if position == n - 1:
                    count = 1
                else:
                    count = completion_count(new_odd, new_even, 1 - parity)

                if count == 0:
                    continue

                if k > count:
                    k -= count
                else:
                    result.append(value)
                    used.add(value)
                    odd, even = new_odd, new_even
                    expected_parity = 1 - parity
                    break
            else:
                return []

        return result

