MOD = 998244353

def compose(r, t):
    res = 0
    for i in range(2):
        for j in range(2):
            if r & (1 << (2 * i + j)):
                for k in range(2):
                    if t & (1 << (2 * j + k)):
                        res |= 1 << (2 * i + k)
    return res

def main():
