    identity = 1 | 8
    up = 2       # 0 -> 1
    down = 4     # 1 -> 0
    marked_zero = 1 | 2 | 8   # 0->0, 0->1, 1->1
    marked_one = 1 | 4 | 8    # 0->0, 1->0, 1->1

    trans_up = [0] * 16
    trans_down = [0] * 16
    trans_mzero = [0] * 16
    trans_mone = [0] * 16

    for r in range(16):
        trans_up[r] = compose(r, up)
        trans_down[r] = compose(r, down)
        trans_mzero[r] = compose(r, marked_zero)
        trans_mone[r] = compose(r, marked_one)

    dp = [0] * 16
    dp[identity] = 1

    for i in range(n):
        nd = [0] * 16
        if s[i] == 48:
            for r in range(16):
                v = dp[r]
                if v:
                    nd[trans_up[r]] += v
