def solve_case(n, a_str, b_str):
    a = [i for i, c in enumerate(a_str) if c == "1"]
    b = [i for i, c in enumerate(b_str) if c == "1"]
    m = len(a)
    k = len(b)

    if m < k:
        return -1

    def feasible(d):
        pos = 0

        for i in range(k - 1):
            cur = b[i]

            if pos >= m or a[pos] < cur - d or a[pos] > cur + d:
                return False

            q = pos + 1
            next_low = b[i + 1] - d
            while q < m and a[q] < next_low:
                q += 1

            remaining_targets = k - i - 1
            if q >= m or q > m - remaining_targets:
                return False

            if a[q - 1] > cur + d:
                return False

            if a[q] > b[i + 1] + d:
                return False

            pos = q

        last = b[-1]
        return (
            pos < m
            and a[pos] >= last - d
            and a[-1] <= last + d
        )

    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1

    return lo


