from typing import List


class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side
        positions = []

        for x, y in points:
            if y == 0:
                t = x
            elif x == side:
                t = side + y
            elif y == side:
                t = 3 * side - x
            else:
                t = 4 * side - y
            positions.append(t)

        positions.sort()
        n = len(positions)
        extended = positions + [p + perimeter for p in positions]

        def feasible(distance: int) -> bool:
            for start in range(n):
                current = start
                limit = start + n

                for _ in range(k - 1):
                    target = extended[current] + distance
                    current = bisect_left(
                        extended, target, current + 1, limit
                    )
                    if current >= limit:
                        break
                else:
                    if extended[start] + perimeter - extended[current] >= distance:
                        return True

            return False

        low, high = 0, side
        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1

        return low

