        for j, ch in enumerate(row):
            if ch != 45:  # '-'
                c = ch - 97
                incoming[j][c].append(i)
                outgoing_mask[i][c] |= 1 << j

                idx = i * n + j
                if dist[idx] == -1:
                    dist[idx] = 1

