        for c in range(26):
            mask = outgoing_mask[y][c]
            if not mask:
                continue

            for u in incoming[x][c]:
                candidates = mask & unvisited[u]
                while candidates:
                    bit = candidates & -candidates
                    candidates -= bit
                    v = bit.bit_length() - 1

                    unvisited[u] &= ~bit
                    nd = d + 2
                    dist[u * n + v] = nd
                    heapq.heappush(heap, (nd, u, v))

    out = []
    for i in range(n):
        out.append(" ".join(map(str, dist[i * n:(i + 1) * n])))
    sys.stdout.write("\n".join(out))


