class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def find_occurrences(pattern: str):
            if not pattern:
                return []

            m = len(pattern)
            lps = [0] * m
            j = 0

            for i in range(1, m):
                while j > 0 and pattern[i] != pattern[j]:
                    j = lps[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                    lps[i] = j

            occurrences = []
            j = 0

            for i, ch in enumerate(s):
                while j > 0 and ch != pattern[j]:
                    j = lps[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    occurrences.append(i - m + 1)
                    j = lps[j - 1]

            return occurrences

        occ_a = find_occurrences(a)
        occ_b = find_occurrences(b)
        occ_c = find_occurrences(c)

        def first_occurrence(occurrences, pattern_length, position):
            if pattern_length == 0:
                return position if position <= n else -1

            index = bisect_left(occurrences, position)
            return occurrences[index] if index < len(occurrences) else -1

        if a:
            candidate_starts = occ_a
        else:
            candidate_starts = range(n + 1)

        answer = float('inf')
        len_a = len(a)
        len_b = len(b)
        len_c = len(c)

        for start in candidate_starts:
            after_a = start + len_a

            b_start = first_occurrence(occ_b, len_b, after_a)
            if b_start == -1:
                continue

            after_b = b_start + len_b

            c_start = first_occurrence(occ_c, len_c, after_b)
            if c_start == -1:
                continue

            end = c_start + len_c
            answer = min(answer, end - start)

        return -1 if answer == float('inf') else answer

