    max_a = 1000
    spf = list(range(max_a + 1))
    for i in range(2, int(max_a ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, max_a + 1, i):
                if spf[j] == j:
                    spf[j] = i

    occurrences = {}

    for idx, value in enumerate(a):
        x = value
        while x > 1:
            p = spf[x]
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            if p not in occurrences:
                occurrences[p] = [0] * (n - 1)
            occurrences[p][idx] = e

    answer = 1

    for p, exps in occurrences.items():
        total = sum(exps)

        pow_p = [1] * (total + 1)
        for i in range(1, total + 1):
            pow_p[i] = pow_p[i - 1] * p % MOD

        dp = [0] * (total + 1)
        dp[0] = 1
        current_max = 0

        for edge in range(n - 1):
            e = exps[edge]
            processed = edge + 1
            ndp = [0] * (total + 1)

            if e == 0:
                for h in range(current_max + 1):
                    v = dp[h]
                    if v:
                        ndp[h] = v * pow_p[h] % MOD
            else:
                # Factors used when a new minimum is reached:
                # p^((e-h) * processed), for h < e.
                base = pow(p, processed, MOD)
                shift = [1] * (e + 1)
                for k in range(1, e + 1):
                    shift[k] = shift[k - 1] * base % MOD

                for h in range(current_max + 1):
                    v = dp[h]
                    if not v:
                        continue

                    # Increment +e
                    nh = h + e
                    ndp[nh] = (ndp[nh] + v * pow_p[nh]) % MOD

                    # Increment -e
                    if h >= e:
                        nh = h - e
                        ndp[nh] = (ndp[nh] + v * pow_p[nh]) % MOD
                    else:
                        ndp[0] = (ndp[0] + v * shift[e - h]) % MOD

                current_max += e

            dp = ndp

        contribution = sum(dp) % MOD
        answer = answer * contribution % MOD

    print(answer)

