class Solution:
    def countSubstrings(self, s: str) -> int:
        dp = [[0] * m for m in range(1, 10)]
        answer = 0

        for ch in s:
            digit = ord(ch) - ord('0')

            for m in range(1, 10):
                previous = dp[m - 1]
                current = [0] * m

                current[digit % m] += 1  # Substring consisting only of this digit

                for remainder, count in enumerate(previous):
                    current[(remainder * 10 + digit) % m] += count

                dp[m - 1] = current

            if digit != 0:
                answer += dp[digit - 1][0]

        return answer

import sys

MOD = 998244353
PRIMITIVE_ROOT = 3
INVERSE_ROOT = 332748118


def ntt(a, invert):
    n = len(a)

    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    root = INVERSE_ROOT if invert else PRIMITIVE_ROOT

    while length <= n:
        wlen = pow(root, (MOD - 1) // length, MOD)
        half = length >> 1

        for start in range(0, n, length):
            w = 1
            end = start + half
            j = start
            while j < end:
                u = a[j]
                v = a[j + half] * w % MOD

                x = u + v
                if x >= MOD:
                    x -= MOD
                a[j] = x

                x = u - v
                if x < 0:
                    x += MOD
                a[j + half] = x

                w = w * wlen % MOD
                j += 1

        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


