    for i in range(1, n + 1):
        present[data[i]] = 1
    del data

    size = 1
    needed = 2 * present_max + 1
    while size < needed:
        size <<= 1

    poly = [0] * size
    for value in range(1, present_max + 1):
        if present[value]:
