    ntt(poly, False)

    for i in range(size):
        poly[i] = poly[i] * poly[i] % MOD

    ntt(poly, True)

    answer = 0
    for middle in range(1, present_max + 1):
        if present[middle]:
            answer += (poly[middle << 1] - 1) // 2

    print(answer)


