def solve():
    input = sys.stdin.buffer.readline
    N, X = map(int, input().split())

    foods = [[], [], []]
    total = [0, 0, 0]

    for _ in range(N):
        v, a, c = map(int, input().split())
        v -= 1
        foods[v].append((a, c))
        total[v] += a

    best = []

    for group in foods:
        dp = [0] * (X + 1)

        for amount, calories in group:
            for capacity in range(X, calories - 1, -1):
                candidate = dp[capacity - calories] + amount
                if candidate > dp[capacity]:
                    dp[capacity] = candidate

        best.append(dp)

    def feasible(target):
        required = 0
        for dp in best:
            cost = bisect_left(dp, target)
            if cost > X:
                return False
            required += cost
        return required <= X

    low = 0
    high = min(total) + 1

    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)


