class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        limit = k - 1

        def count_subarrays(left_ext: int, right_ext: int) -> int:
            def combinations(x: int) -> int:
                if x < 0:
                    return 0
                return (x + 1) * (x + 2) // 2

            return (
                combinations(limit)
                - combinations(limit - left_ext - 1)
                - combinations(limit - right_ext - 1)
                + combinations(limit - left_ext - right_ext - 2)
            )

        def sum_extremes(is_max: bool) -> int:
            prev = [-1] * n
            nxt = [n] * n
            stack = []

            if is_max:
                for i, value in enumerate(nums):
                    while stack and nums[stack[-1]] <= value:
                        stack.pop()
                    if stack:
                        prev[i] = stack[-1]
                    stack.append(i)

                stack.clear()
                for i in range(n - 1, -1, -1):
                    value = nums[i]
                    while stack and nums[stack[-1]] < value:
                        stack.pop()
                    if stack:
                        nxt[i] = stack[-1]
                    stack.append(i)
            else:
                for i, value in enumerate(nums):
                    while stack and nums[stack[-1]] >= value:
                        stack.pop()
                    if stack:
                        prev[i] = stack[-1]
                    stack.append(i)

                stack.clear()
                for i in range(n - 1, -1, -1):
                    value = nums[i]
                    while stack and nums[stack[-1]] > value:
                        stack.pop()
                    if stack:
                        nxt[i] = stack[-1]
                    stack.append(i)

            total = 0
            for i, value in enumerate(nums):
                left_ext = i - prev[i] - 1
                right_ext = nxt[i] - i - 1
                total += value * count_subarrays(left_ext, right_ext)

            return total

        return sum_extremes(True) + sum_extremes(False)

