from array import array


def solve():
    input = sys.stdin.buffer.readline
    N, M = map(int, input().split())

    intervals = []
    complement = []
    regular = []

    for idx in range(M):
        l, r = map(int, input().split())
        intervals.append((l, r))
        complement.append((l, r, idx))
        regular.append((l, r, idx))

    # Coordinates used as states in the greedy interval-cover transitions.
    coords = {1, N + 1}
    for l, r, _ in regular:
        coords.add(l)
        coords.add(r + 1)
    for l, r, _ in complement:
        coords.add(l)

    coords = sorted(coords)
    pos = {x: i for i, x in enumerate(coords)}
    S = len(coords)

    regular_by_l = sorted(regular)
    best_r = [0] * S
    best_id = [-1] * S

    p = 0
    cur_r = 0
    cur_id = -1
    for si, x in enumerate(coords):
        while p < M and regular_by_l[p][0] <= x:
            l, r, idx = regular_by_l[p]
            if r > cur_r:
                cur_r = r
                cur_id = idx
            p += 1
        best_r[si] = cur_r
        best_id[si] = cur_id

    # One greedy transition: cover from x using one interval.
    nxt0 = array('i', [0]) * S
    dead = -1
    for i, x in enumerate(coords):
        if x == N + 1:
            nxt0[i] = i
        elif best_r[i] >= x:
            nxt0[i] = pos[best_r[i] + 1]
        else:
            nxt0[i] = dead

    LOG = (S + 1).bit_length()
    jumps = [nxt0]
    for _ in range(1, LOG):
        prev = jumps[-1]
        cur = array('i', [0]) * S
        for i in range(S):
            q = prev[i]
            cur[i] = -1 if q < 0 else prev[q]
        jumps.append(cur)

    def cover_count(a, b):
        if a > b:
            return 0
        cur = pos.get(a)
        if cur is None:
            cur = bisect_left(coords, a)
        if cur >= S or coords[cur] != a:
            return None

        if coords[cur] > b:
            return 0

        count = 0
        for k in range(LOG - 1, -1, -1):
            q = jumps[k][cur]
            if q >= 0 and coords[q] <= b:
                cur = q
                count += 1 << k

        q = jumps[0][cur]
        if q < 0:
            return None
        if coords[q] <= b:
            return None
        return count + 1

    best_cost = None
    best_kind = None
    best_data = None

    def consider(cost, kind, data):
        nonlocal best_cost, best_kind, best_data
        if cost is not None and (best_cost is None or cost < best_cost):
            best_cost = cost
            best_kind = kind
            best_data = data

    # No complement operations: cover the whole universe by intervals.
    c = cover_count(1, N)
    consider(c, 0, None)

    # One complement operation.
    for l, r, idx in complement:
        c = cover_count(l, r)
        if c is not None:
            consider(c + 1, 1, (idx, l, r))

    # Prepare complement intervals grouped by left endpoint.
    complement.sort()
    groups = []
    i = 0
    while i < M:
        j = i
        l = complement[i][0]
        while j < M and complement[j][0] == l:
            j += 1
        groups.append((i, j))
        i = j

    # Fenwick tree over right endpoints of already processed complement intervals.
    rights = sorted({r for _, r, _ in complement})
    K = len(rights)
    bit = [0] * (K + 1)

    def bit_add(i, v):
        i += 1
        while i <= K:
            bit[i] += v
            i += i & -i

    def bit_sum(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    def bit_kth(k):
        # 1-indexed kth element
        idx = 0
        step = 1 << (K.bit_length() - 1)
        while step:
            ni = idx + step
            if ni <= K and bit[ni] < k:
                idx = ni
                k -= bit[ni]
            step >>= 1
        return idx  # zero-based Fenwick position

    # Two complement operations.
    for gl, gr in groups:
        lval = complement[gl][0]

        # Two smallest right endpoints in this equal-L group.
        group_sorted = sorted(
            (complement[t][1], complement[t][2]) for t in range(gl, gr)
        )

        for t in range(gl, gr):
            l, r, idx = complement[t]

            # Best candidate from earlier groups:
            threshold_rank = bisect_left(rights, l)
            prior_candidate = None
            total_ge = bit_sum(K) - bit_sum(threshold_rank)
            if total_ge > 0:
                rr = rights[bit_kth(bit_sum(threshold_rank) + 1)]
                # Find an interval with this right endpoint among prior groups.
                # Store one such index by scanning a small auxiliary map below.
                prior_candidate = (rr, prior_index_by_r[rr])

            candidate = prior_candidate

            # Best candidate from the same group, excluding itself.
            same_candidate = None
            if len(group_sorted) >= 2:
                if group_sorted[0][1] != idx:
                    same_candidate = group_sorted[0]
                else:
                    same_candidate = group_sorted[1]

            if same_candidate is not None:
                if candidate is None or same_candidate[0] < candidate[0]:
                    candidate = same_candidate

            if candidate is not None:
                rr, other_idx = candidate
                a = l
                b = min(r, rr)
                c = cover_count(a, b)
                if c is not None:
                    consider(c + 2, 2, (idx, other_idx, a, b))

        # Insert this whole group after querying it, so equal-L intervals
        # are not treated as earlier intervals.
        for t in range(gl, gr):
            rr, idx = complement[t][1], complement[t][2]
            bit_add(bisect_left(rights, rr), 1)

        # Rebuild one representative index for each right endpoint among
        # processed intervals. This map is only needed for successor queries.
        prior_index_by_r = {}
        for t in range(0, gr):
            rr, idx = complement[t][1], complement[t][2]
            if rr not in prior_index_by_r:
                prior_index_by_r[rr] = idx

    if best_cost is None:
        print(-1)
        return

    ops = [0] * M

    def reconstruct(a, b):
        chosen = []
        if a > b:
            return chosen
        cur = pos[a]
        while coords[cur] <= b:
            idx = best_id[cur]
            if idx < 0:
                return None
            chosen.append(idx)
            cur = jumps[0][cur]
            if cur < 0:
                return None
        return chosen

    if best_kind == 0:
        selected = reconstruct(1, N)
        if selected is None:
            print(-1)
            return
        for idx in selected:
            ops[idx] = 1

    elif best_kind == 1:
        comp_idx, l, r = best_data
        selected = reconstruct(l, r)
        if selected is None:
            print(-1)
            return
        ops[comp_idx] = 2
        for idx in selected:
            if idx != comp_idx:
                ops[idx] = 1

    else:
        c1, c2, a, b = best_data
        selected = reconstruct(a, b)
        if selected is None:
            print(-1)
            return
        ops[c1] = 2
        ops[c2] = 2
        for idx in selected:
            if idx != c1 and idx != c2:
                ops[idx] = 1

    print(best_cost)
    print(*ops)


