import sys


def mat_mul(a, b, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        ri = res[i]
        ai = a[i]
        for k, x in enumerate(ai):
            if x:
                bk = b[k]
                for j in range(n):
                    ri[j] += x * bk[j]
        for j in range(n):
            ri[j] %= mod
    return res


def mat_pow(a, exponent, mod):
    n = len(a)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1

    while exponent:
        if exponent & 1:
            result = mat_mul(result, a, mod)
        exponent >>= 1
        if exponent:
            a = mat_mul(a, a, mod)
    return result


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, p = data[0], data[1]
    vals = data[2:]
    a = [vals[i * n:(i + 1) * n] for i in range(n)]

    # For p = 2, every entry of B is 1.
    if p == 2:
        v = n & 1
        line = " ".join([str(v)] * n)
        sys.stdout.write("\n".join([line] * n))
        return

    c = [row[:] for row in a]
    zero_count = 0
    zero_diag = []

    for i in range(n):
        for j in range(n):
            if c[i][j] == 0:
                zero_count += 1
                if i == j:
                    zero_diag.append(i)

    ans = mat_pow(c, p, p)

    # Additional terms caused by using a zero entry p-1 times.
    for r in zero_diag:
        for j in range(n):
            ans[r][j] += a[r][j]
            ans[r][j] %= p
        for i in range(n):
            ans[i][r] += a[i][r]
            ans[i][r] %= p

    # For p = 3, an off-diagonal zero can occur twice with the
    # reverse fixed edge between the two occurrences.
    if p == 3:
        for r in range(n):
            for cidx in range(n):
                if r != cidx and a[r][cidx] == 0:
                    ans[r][cidx] += a[cidx][r]
                    ans[r][cidx] %= p

    factor = 1 if zero_count % 2 == 0 else p - 1
    for i in range(n):
        for j in range(n):
            ans[i][j] = ans[i][j] * factor % p

    sys.stdout.write("\n".join(" ".join(map(str, row)) for row in ans))


