class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)

        items = sorted(
            ((idx, interval) for idx, interval in enumerate(intervals)),
            key=lambda x: x[1][1]
        )
        ends = [interval[1] for _, interval in items]

        # dp[i][k] = (maximum score, lexicographically smallest tuple)
        # using exactly k intervals among the first i sorted intervals.
        dp = [[(-1, ()) for _ in range(5)] for _ in range(n + 1)]
        for i in range(n + 1):
            dp[i][0] = (0, ())

        for i, (idx, (left, right, weight)) in enumerate(items):
            previous = dp[i]
            current = dp[i + 1]

            for k in range(1, 5):
                best_score, best_indices = previous[k]

                predecessor = bisect_left(ends, left)
                base_score, base_indices = dp[predecessor][k - 1]

                if base_score >= 0:
                    pos = bisect_left(base_indices, idx)
                    candidate_indices = (
                        base_indices[:pos] + (idx,) + base_indices[pos:]
                    )
                    candidate_score = base_score + weight

                    if (
                        candidate_score > best_score
                        or (
                            candidate_score == best_score
                            and candidate_indices < best_indices
                        )
                    ):
                        best_score = candidate_score
                        best_indices = candidate_indices

                current[k] = (best_score, best_indices)

        answer_score = -1
        answer_indices = ()

        for k in range(5):
            score, indices = dp[n][k]
            if (
                score > answer_score
                or (score == answer_score and indices < answer_indices)
            ):
                answer_score = score
                answer_indices = indices

        return list(answer_indices)

from typing import List


class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        values = {v: i for i, v in enumerate(set(nums))}
        m = len(values)

        NEG = -10**30
        INF = 10**30

        mn = [0] * (4 * m)
        second_mn = [0] * (4 * m)
        cnt_mn = [0] * (4 * m)
        mx = [0] * (4 * m)
        lazy_add = [0] * (4 * m)

        def build(node: int, left: int, right: int) -> None:
            mn[node] = NEG
            second_mn[node] = INF
            cnt_mn[node] = right - left
            mx[node] = NEG
            if right - left > 1:
                mid = (left + right) // 2
                build(node * 2, left, mid)
                build(node * 2 + 1, mid, right)

        def apply_add(node: int, value: int) -> None:
            mn[node] += value
            if second_mn[node] < INF // 2:
                second_mn[node] += value
            mx[node] += value
            lazy_add[node] += value

        def apply_chmax(node: int, value: int) -> None:
            if value <= mn[node]:
                return
            if mx[node] == mn[node]:
                mx[node] = value
            mn[node] = value

        def push(node: int) -> None:
            value = lazy_add[node]
            if value:
                apply_add(node * 2, value)
                apply_add(node * 2 + 1, value)
                lazy_add[node] = 0

            parent_min = mn[node]
            if mn[node * 2] < parent_min:
                apply_chmax(node * 2, parent_min)
            if mn[node * 2 + 1] < parent_min:
                apply_chmax(node * 2 + 1, parent_min)

        def pull(node: int) -> None:
            left = node * 2
            right = left + 1

            mn_value = min(mn[left], mn[right])
            mn[node] = mn_value
            cnt_mn[node] = 0
            next_min = INF

            if mn[left] == mn_value:
                cnt_mn[node] += cnt_mn[left]
                next_min = min(next_min, second_mn[left])
            else:
                next_min = min(next_min, mn[left])

            if mn[right] == mn_value:
                cnt_mn[node] += cnt_mn[right]
                next_min = min(next_min, second_mn[right])
            else:
                next_min = min(next_min, mn[right])

            second_mn[node] = next_min
            mx[node] = max(mx[left], mx[right])

        def range_add(
            node: int, left: int, right: int, ql: int, qr: int, value: int
        ) -> None:
            if qr <= left or right <= ql:
                return
            if ql <= left and right <= qr:
                apply_add(node, value)
                return

            push(node)
            mid = (left + right) // 2
            range_add(node * 2, left, mid, ql, qr, value)
            range_add(node * 2 + 1, mid, right, ql, qr, value)
            pull(node)

        def range_chmax(
            node: int, left: int, right: int, ql: int, qr: int, value: int
        ) -> None:
            if qr <= left or right <= ql or value <= mn[node]:
                return

            if ql <= left and right <= qr and value < second_mn[node]:
                apply_chmax(node, value)
                return

            push(node)
            mid = (left + right) // 2
            range_chmax(node * 2, left, mid, ql, qr, value)
            range_chmax(node * 2 + 1, mid, right, ql, qr, value)
            pull(node)

        build(1, 0, m)

        current = nums[0]
        answer = nums[0]

        for value in nums:
            if value == nums[0]:
                current = nums[0]
            else:
                current = max(value, current + value)
            answer = max(answer, current)

        for value in nums:
            excluded = values[value]

            if excluded > 0:
                range_add(1, 0, m, 0, excluded, value)
                range_chmax(1, 0, m, 0, excluded, value)

            if excluded + 1 < m:
                range_add(1, 0, m, excluded + 1, m, value)
                range_chmax(1, 0, m, excluded + 1, m, value)

            answer = max(answer, mx[1])

        return answer

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        # Choose which of the n - 1 adjacent pairs are equal.
        equal_positions = 1
        for i in range(1, k + 1):
            equal_positions = equal_positions * (n - i) % MOD
            equal_positions = equal_positions * pow(i, MOD - 2, MOD) % MOD

        # Choose the first value, then choose a different value at each change.
        return (
            equal_positions
            * m
            * pow(m - 1, n - 1 - k, MOD)
        ) % MOD

