def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    total = sum(a)
    answer = (n + 1) * total

    max_sum = 2 * max(a)
    modulus = 2

    while modulus <= max_sum:
        mask = modulus - 1
        groups = {}

        for x in a:
            r = x & mask
            group = groups.get(r)
            if group is None:
                groups[r] = [1, x]
            else:
                group[0] += 1
                group[1] += x

        divisible_sum = 0

        for r, (count, value_sum) in groups.items():
            if r == 0 or r * 2 == modulus:
                divisible_sum += (count + 1) * value_sum
            elif r * 2 < modulus:
                other = groups.get(modulus - r)
                if other is not None:
                    other_count, other_sum = other
                    divisible_sum += other_count * value_sum + count * other_sum

        answer -= divisible_sum // modulus
        modulus <<= 1

    print(answer)

