import sys


def solve():
    input = sys.stdin.buffer.readline
    n = int(input())
    a = list(map(int, input().split()))

    pref = [0] * (n + 1)
    for i, v in enumerate(a):
        pref[i + 1] = pref[i] + v

    size = 1
    while size < n:
        size <<= 1

    seg = [0] * (size << 1)
    seg[size:size + n] = a
    for i in range(size - 1, 0, -1):
        seg[i] = max(seg[i << 1], seg[i << 1 | 1])

    def first_ge(start, x):
        if start >= n:
            return n
        l = start + size
        r = n + size
        while l < r:
            if l & 1:
                if seg[l] >= x:
                    node = l
                    while node < size:
                        left = node << 1
                        if seg[left] >= x:
                            node = left
                        else:
                            node = left | 1
                    return node - size
                l += 1
            l >>= 1
            r >>= 1
        return n

    def last_ge(end, x):
        if end <= 0:
            return -1
        l = size
        r = end + size
        while l < r:
            if r & 1:
                r -= 1
                if seg[r] >= x:
                    node = r
                    while node < size:
                        right = node << 1 | 1
                        if seg[right] >= x:
                            node = right
                        else:
                            node = right - 1
                    return node - size
            l >>= 1
            r >>= 1
        return -1

    ans = [0] * n

    for start in range(n):
        left = right = start
        total = a[start]

        while True:
            old_left = left
            old_right = right

            if left > 0 and a[left - 1] < total:
                p = last_ge(left, total)
                new_left = p + 1
                total += pref[left] - pref[new_left]
                left = new_left

            if right + 1 < n and a[right + 1] < total:
                p = first_ge(right + 1, total)
                new_right = n - 1 if p == n else p - 1
                total += pref[new_right + 1] - pref[right + 1]
                right = new_right

            if left == old_left and right == old_right:
                break

        ans[start] = total

    sys.stdout.write(" ".join(map(str, ans)))


if __name__ == "__main__":
    solve()

from typing import List


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        size = [1] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        components = n

        def union(a: int, b: int) -> None:
            nonlocal components
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]
            components -= 1

        index = {value: i for i, value in enumerate(nums) if value <= threshold}
        representative = [-1] * (threshold + 1)

        for value, idx in index.items():
            for multiple in range(value, threshold + 1, value):
                if representative[multiple] == -1:
                    representative[multiple] = idx
                else:
                    union(idx, representative[multiple])

        return components
